export interface QuestStory {
    id: number
    quests: QuestItem[]
}

export interface QuestItem {
    id: number
    name: string
    desc?: string
    nodes?: QuestNode[]
    startIds?: string[]
}

export type ImprType = "All" | "Any" | "Empathy" | "Chaos" | "Morality" | "Wisdom" | "Benefit"

export interface Dialogue {
    id: number
    content?: string
    voice?: string
    npc?: number
    speakerName?: string
    next?: number
    impr?: [number, ImprType, number]
    options?: DialogueOption[]
}

export interface QuestNode {
    id: string
    type: string
    name: string
    next?: string[]
    srId?: number
    pos?: [number, number]
    dialogues?: Dialogue[]
    answers?: DetectiveAnswer[]
    questions?: DetectiveQuestion[]
}

export interface DialogueOption {
    id: number
    content: string
    voice?: string
    npc?: number
    next?: number
    impr?: [number, ImprType, number]
    imprCheck?: [number, ImprType, number]
    options?: DialogueOption[]
}

export interface DetectiveQuestion {
    id: number
    name: string
    answers: number[]
    tips: string
}

export interface DetectiveAnswer {
    id: number
    qid: number
    name: string
    desc: string
    icon: string
}

